    }

    async function startShare() {
      try {
        localStream = await navigator.mediaDevices.getDisplayMedia({ video: { frameRate: 30 }, audio: true });
        video.srcObject = localStream;
        isHost = true;
        setLive(true);
        document.getElementById('shareBtn').classList.add('hidden');
        document.getElementById('stopBtn').classList.remove('hidden');
        setStatus('Compartilhando tela. Outras pessoas podem clicar em “Assistir tela”.');
        localStream.getVideoTracks()[0].onended = stopShare;
        send({ type: 'host-live', from: myId });
      } catch (e) {
        setStatus('Permissão negada ou tela não selecionada.');
      }
    }

    function stopShare() {
      Object.values(peers).forEach((pc) => pc.close());
      peers = {};
      if (localStream) { localStream.getTracks().forEach((t) => t.stop()); localStream = null; }
      video.srcObject = null;
      isHost = false;
      watching = false;
      setLive(false);
      document.getElementById('shareBtn').classList.remove('hidden');
      document.getElementById('stopBtn').classList.add('hidden');
      setStatus('Compartilhamento encerrado.');
      send({ type: 'host-stopped', from: myId });
    }

    async function requestStream() {
      if (!channel) return setStatus('Entre em uma sala primeiro.');
      watching = true;
      setStatus('Pedindo acesso à tela do apresentador...');
      send({ type: 'request-stream', from: myId });
    }

    async function handleSignal(p) {
      if (p.type === 'request-stream' && isHost && localStream) {
        const pc = createPeer(p.from, 'host');
        localStream.getTracks().forEach((t) => pc.addTrack(t, localStream));
        const offer = await pc.createOffer();
        await pc.setLocalDescription(offer);
        send({ type: 'offer', to: p.from, from: 'host', sdp: offer });
      }
      if (p.type === 'offer' && p.to === myId) {
        const pc = createPeer(p.from, myId);
        await pc.setRemoteDescription(p.sdp);
        const answer = await pc.createAnswer();
        await pc.setLocalDescription(answer);
        send({ type: 'answer', to: p.from, from: myId, sdp: answer });
      }
      if (p.type === 'answer' && p.to === 'host' && peers[p.from]) {
        await peers[p.from].setRemoteDescription(p.sdp);
      }
      if (p.type === 'ice' && peers[p.from]) {
        try { await peers[p.from].addIceCandidate(p.candidate); } catch (e) {}
      }
    }

