  const pixNameInput = document.getElementById('pixName');
  const pixCityInput = document.getElementById('pixCity');
  const pixAmountInput = document.getElementById('pixAmount');
  const pixCode = document.getElementById('pixCode');
  const pixQr = document.getElementById('pixQr');
  const pixQrShell = document.getElementById('pixQrShell');
  const pixQrEmpty = document.getElementById('pixQrEmpty');
  const pixQrSource = document.getElementById('pixQrSource');
  const pixFeedback = document.getElementById('pixFeedback');
  const pixCopyBtn = document.getElementById('pixCopyBtn');
  const pixCopyBtnDefault = pixCopyBtn.innerHTML;

  function setPixFeedback(text, type) {
    pixFeedback.textContent = text;
    pixFeedback.className = 'pix-feedback' + (type ? ' ' + type : '');
  }

  function clearPixResult() {
    pixCode.value = '';
    pixQr.removeAttribute('src');
    pixQr.classList.add('hidden');
    pixQrEmpty.classList.remove('hidden');
    pixQrShell.classList.remove('has-qr');
    pixQrSource.innerHTML = '';
  }

  function pixEmv(id, value) {
    return id + String(value.length).padStart(2, '0') + value;
  }

  function pixCrc16(payload) {
    let crc = 0xFFFF;
    for (let i = 0; i < payload.length; i++) {
      crc ^= payload.charCodeAt(i) << 8;
      for (let bit = 0; bit < 8; bit++) {
        crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1);
        crc &= 0xFFFF;
      }
    }
    return crc.toString(16).toUpperCase().padStart(4, '0');
  }

  function normalizePixText(value, maxLength) {
    return value
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^A-Za-z0-9 ]/g, '')
      .replace(/\s+/g, ' ')
      .trim()
      .toUpperCase()
      .slice(0, maxLength);
  }

  function normalizePixKey(raw) {
    const key = raw.trim();
    if (!key) return '';

    if (key.includes('@')) return key.toLowerCase();
    if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(key)) {
      return key.toLowerCase();
    }
    if (/^[0-9a-f]{32}$/i.test(key)) return key.toLowerCase();
    if (key.startsWith('+')) return '+' + key.replace(/\D/g, '');

    const digits = key.replace(/\D/g, '');
    const looksLikeDocument = /[./]/.test(key);

    if ((digits.length === 11 || digits.length === 14) && (looksLikeDocument || /^\d+$/.test(key))) {
      return digits;
    }
    if ((digits.length === 10 || digits.length === 11) && /[()\s-]/.test(key)) {
      return '+55' + digits;
    }
    if (digits.length === 12 || digits.length === 13) return '+' + digits;

    return key;
  }

  function renderPixQr(payload) {
    if (typeof QRCode === 'undefined') {
      throw new Error('Biblioteca de QR Code indisponível.');
    }

    pixQrSource.innerHTML = '';
    new QRCode(pixQrSource, {
      text: payload,
      width: 512,
      height: 512,
      colorDark: '#0b0d12',
      colorLight: '#ffffff',
      correctLevel: QRCode.CorrectLevel.M
    });

    const canvas = pixQrSource.querySelector('canvas');
    const image = pixQrSource.querySelector('img');
    const dataUrl = canvas ? canvas.toDataURL('image/png') : (image ? image.src : '');

    if (!dataUrl) throw new Error('Não foi possível desenhar o QR Code.');

    pixQr.src = dataUrl;
    pixQr.classList.remove('hidden');
    pixQrEmpty.classList.add('hidden');
    pixQrShell.classList.add('has-qr');
  }

  function generatePix() {
    const key = normalizePixKey(pixKeyInput.value);
    if (!key) {
      setPixFeedback('Informe sua chave Pix para continuar.', 'error');
      pixKeyInput.focus();
      return false;
    }

    const name = normalizePixText(pixNameInput.value, 25);
    if (!name) {
      setPixFeedback('Informe o nome do recebedor.', 'error');
      pixNameInput.focus();
      return false;
    }

    const city = normalizePixText(pixCityInput.value, 15) || 'PARANA';
    const amountRaw = pixAmountInput.value.trim();
    let amount = '';

    if (amountRaw !== '') {
      const parsedAmount = Number(amountRaw.replace(',', '.'));
      if (!Number.isFinite(parsedAmount) || parsedAmount < 0) {
        setPixFeedback('Informe um valor válido ou deixe o campo em branco.', 'error');
        pixAmountInput.focus();
        return false;
      }
      if (parsedAmount > 0) amount = parsedAmount.toFixed(2);
    }

    pixKeyInput.value = key;
    pixNameInput.value = name;
    pixCityInput.value = city;

    const merchantAccount =
      pixEmv('00', 'br.gov.bcb.pix') +
      pixEmv('01', key);

    let payload =
      pixEmv('00', '01') +
      pixEmv('26', merchantAccount) +
      pixEmv('52', '0000') +
      pixEmv('53', '986');

    if (amount) payload += pixEmv('54', amount);

    payload +=
      pixEmv('58', 'BR') +
      pixEmv('59', name) +
      pixEmv('60', city) +
      pixEmv('62', pixEmv('05', '***'));

    payload += '6304';
    const code = payload + pixCrc16(payload);

    clearPixResult();
    pixCode.value = code;

    try {
      renderPixQr(code);
      setPixFeedback('QR Code gerado. Código Pix pronto para copiar.', 'ok');
    } catch (error) {
      setPixFeedback('Código gerado, mas o QR Code não pôde ser exibido. Copie o código abaixo.', 'error');
    }

    return true;
  }

  async function copyPix() {
    if (!pixCode.value.trim() && !generatePix()) return;

    try {
      await navigator.clipboard.writeText(pixCode.value);
    } catch (error) {
      pixCode.focus();
      pixCode.select();

      let copied = false;
      try { copied = document.execCommand('copy'); } catch (fallbackError) { copied = false; }

      if (!copied) {
        setPixFeedback('Não foi possível copiar automaticamente. Selecione o código e copie manualmente.', 'error');
        return;
      }
    }

    setPixFeedback('Código Pix copiado para a área de transferência.', 'ok');
    pixCopyBtn.textContent = 'Copiado!';
    setTimeout(() => {
      pixCopyBtn.innerHTML = pixCopyBtnDefault;
    }, 1800);
  }

  [pixKeyInput, pixNameInput, pixCityInput, pixAmountInput].forEach((input) => {
    input.addEventListener('input', () => {
      if (pixCode.value) {
        clearPixResult();
        setPixFeedback('Dados alterados. Gere um novo QR Code.');
      }
    });

    input.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        event.preventDefault();
        generatePix();
      }
    });
  });

  pixCode.addEventListener('click', () => pixCode.select());
</script>

