*{box-sizing:border-box;margin:0;padding:0;font-family:Inter,system-ui,Arial,sans-serif}
:root{--bg:#1e1f22;--sidebar:#2b2d31;--chat:#313338;--input:#383a40;--text:#dbdee1;--muted:#949ba4;--brand:#5865f2}
body{height:100vh;display:flex;background:var(--bg);color:var(--text);overflow:hidden}
.serverbar{width:72px;background:var(--bg);padding:12px 0;display:flex;flex-direction:column;align-items:center}
.server{width:48px;height:48px;border-radius:16px;background:#313338;display:flex;align-items:center;justify-content:center;font-weight:800}
.server.active{background:var(--brand);color:#fff;border-radius:14px}
.sidebar{width:240px;background:var(--sidebar);display:flex;flex-direction:column}
.userbar{height:52px;background:#232428;display:flex;align-items:center;justify-content:space-between;padding:0 10px;font-weight:600}
.avatar{border-radius:50%;background:var(--brand);display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0}
.userbar .avatar{width:32px;height:32px;font-size:14px}
.dot{width:8px;height:8px;border-radius:50%;background:#23a55a;margin-left:6px;display:inline-block}
.channels{flex:1;overflow-y:auto;padding:10px 8px}
.channel{display:flex;gap:8px;padding:7px 8px;border-radius:6px;color:var(--muted);cursor:pointer;font-size:14px}
.channel:hover{background:#35373c;color:var(--text)}
