      <div class="avatar" id="meAvatar">M</div>
      <span id="meName">...</span>
      <span class="dot"></span>
    </div>
    <button onclick="logout()" title="Sair">⎋</button>
  </div>
  <div class="channels" id="channels"></div>
</aside>


<main class="main">
  <header class="chat-header">
    <span class="hash">#</span>
    <span id="channelName">geral</span>
  </header>


  <section class="messages" id="messages"></section>


  <div class="composer">
    <form id="form">
      <input id="input" placeholder="Conversar em #geral">
      <button>➤</button>
    </form>
  </div>
</main>


<aside class="members">
  <div style="font-size:12px;color:var(--muted);margin-bottom:8px">MEMBROS</div>
  <div id="members"></div>
</aside>


<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/dist/umd/supabase.js"></script>
<script>
const sb=supabase.createClient(
  'https://jldkrcgfjvaalouoxgqa.supabase.co',
  'sb_publishable_igul1pyZmV8V4wmm1VBxfg_YyzEXToO'
);


let me=null,current='geral',channels=[];


function esc(t){return t.replace(/</g,'&lt;')}
function ini(n){return (n||'?')[0].toUpperCase()}


function logout(){
  sb.auth.signOut().then(()=>{
    location.href='miikacord-login.html';
  });
}


function renderChannels(){
  channelsEl.innerHTML=channels.map(c=>`
    <div class="channel ${c.id===current?'active':''}" onclick="openChannel('${c.id}')">
      <span class="hash">#</span>${c.name}
    </div>
  `).join('');
}


function msgHTML(m){
  return `
  <div class="msg">
    <div class="avatar" style="background:${m.color||'#5865f2'}">${ini(m.username)}</div>
    <div>
      <div>
        <span class="name">${esc(m.username)}</span>
        <span class="time">${new Date(m.created_at).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span>
      </div>
      <div class="content">${esc(m.content)}</div>
    </div>
  </div>`;
}


function renderMessages(msgs){
  messagesEl.innerHTML=msgs.map(msgHTML).join('');
  messagesEl.scrollTop=1e9;
}


async function loadMessages(){
  const {data}=await sb.from('messages')
    .select('*')
    .eq('channel_id',current)
    .order('created_at');


  renderMessages(data||[]);
}


function openChannel(id){
  current=id;
  renderChannels();
  loadMessages();
  input.placeholder=`Conversar em #${id}`;
}


async function init(){
  const {data:{session}}=await sb.auth.getSession();


  if(!session){
    location.href='miikacord-login.html';
    return;
  }


  const uid=session.user.id;


  const {data:profile}=await sb.from('profiles')
    .select('*')
    .eq('id',uid)
    .single();


  me=profile||{
    username:session.user.email.split('@')[0],
    color:'#5865f2',
    status:'Online'
  };


  meName.textContent=me.username;
  meAvatar.textContent=ini(me.username);
  meAvatar.style.background=me.color;


  const [{data:ch},{data:profs}]=await Promise.all([
    sb.from('channels').select('*').order('created_at'),
    sb.from('profiles').select('*')
  ]);


  channels=ch||[];
  renderChannels();


  membersEl.innerHTML=(profs||[]).map(u=>`
    <div class="member">
      <div class="avatar" style="background:${u.color}">${ini(u.username)}</div>
      <div>${esc(u.username)}<small>${u.status||'Online'}</small></div>
    </div>
  `).join('');


  sb.channel('miikacord-realtime')
    .on('postgres_changes',{
      event:'INSERT',
      schema:'public',
      table:'messages'
    },p=>{
      if(p.new.channel_id===current){
        messagesEl.insertAdjacentHTML('beforeend',msgHTML(p.new));
        messagesEl.scrollTop=1e9;
      }
    })
    .subscribe();


  openChannel('geral');
}


form.addEventListener('submit',async e=>{
  e.preventDefault();


  const text=input.value.trim();
  if(!text||!me)return;


  input.value='';


  await sb.from('messages').insert({
    channel_id:current,
    username:me.username,
    color:me.color,
    content:text
  });
});


init();
</script>
</body>
</html>

